#!/usr/bin/env node
// mockup-config-check.mjs
// Lists the mockup blueprint questions a project's
// ${aiDir}/conventions/mockup-design.md has never been asked in their current
// form, and the heading renames it has not had (`update` and
// `feature-mockup-review` run it); applies the renames and stamps the file.
//
// The file is generated by `/myspec:setup mockup` and holds the project's
// answers. Two tables in the blueprint carry what a release changes:
//
//   ## Question changes   | Question | Writes | Since | Present when |
//   ## Heading renames    | Old | New | Since |
//
// Each row's version is compared with the file's frontmatter
// `myspec_version` (a file without a readable stamp counts as BASE_VERSION,
// the release that added the blueprint). A question row newer than the stamp
// is listed (the newest per question and target) unless the file already
// holds it: a `(new section)` row whose heading exists, or a row whose
// *Present when* text is in its target section. A rename row is listed
// whenever the file has the old heading and not the new one (both
// headings: a conflict, reported for a hand merge).
// The body is read only for those two tests and edited only by
// --apply-renames, which rewrites heading lines and nothing else.
//
// Usage:
//   node <plugin>/lib/mockup-config-check.mjs [--root <checkout>] [--file <path>] [--blueprint <path>]
//        [--apply-renames | --stamp]
//
// --root defaults to the nearest directory at or above the current one that
// holds .myspec.json. --file and --blueprint resolve against it.
// --stamp sets `myspec_version` to the plugin's own version (its
// framework-files/manifest.json), adding the key when absent. It edits an
// existing frontmatter block only (line 1 `---`, a BOM allowed, YAML lines
// only); any other file is refused, never given a block.
//
// Exit: 0 nothing to ask or rename (or applied / stamped), 3 questions to ask
// or renames to apply, 4 the file does not exist, 2 usage error, a blueprint
// or manifest it cannot read or parse (a table line it cannot read is an
// error, never skipped), a file it cannot stamp, or a file it cannot read or
// write.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { aiDirFor, scalarField } from './memory-files.mjs';
import { compareVersions, normalizeVersion } from './upgrade-route.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = join(HERE, '..');
export const BASE_VERSION = '1.20.0';
export const TABLE_HEADING = '## Question changes';
export const RENAMES_HEADING = '## Heading renames';
const BOM = '﻿';
// The *Writes* forms the blueprint's procedure knows how to write.
const HEADING_CELL = /^#{2,3} \S/;
const WRITES = /^(?:## \S.*? \((?:new section|in section|replaces section)\)|\.myspec\.json mockups\.[A-Za-z0-9_.-]+)$/;
// A line a YAML frontmatter block can hold; a block with any other line is a
// pair of horizontal rules, not frontmatter.
const YAML_LINE = /^(?:\s*$|\s*#|[A-Za-z_][\w-]*\s*:|\s+\S|- )/;

// A table row's cells, split on unescaped pipes; `\|` becomes `|`.
export const cells = (line) =>
  line
    .trim()
    .replace(/^\|/, '')
    .replace(/(?<!\\)\|$/, '')
    .split(/(?<!\\)\|/)
    .map((c) => c.trim().replace(/\\\|/g, '|'));

// The rows of the table under `heading`, as arrays of cells with the line
// they came from. The table runs from its header row (which must match
// `header`) to the next heading; blank lines may sit between rows, any other
// line is an error, so a malformed row never goes unnoticed.
function tableUnder(lines, heading, header) {
  const start = lines.findIndex((l) => l.trim() === heading);

  if (start < 0) {
    throw new Error(`no "${heading}" section`);
  }

  const want = `| ${header.join(' | ')} |`;
  const rows = [];
  let seenHeader = false;

  for (let i = start + 1; i < lines.length && !/^#{1,3} /.test(lines[i]); i++) {
    const t = lines[i].trim();

    if (!seenHeader) {
      if (t.startsWith('|')) {
        // The first table line must be the header, or the first row would be
        // taken for it and never read.
        if (cells(t).map((c) => c.toLowerCase()).join('|') !== header.map((c) => c.toLowerCase()).join('|')) {
          throw new Error(`the ${heading} table must start with its header row ${want}, found "${t}"`);
        }

        seenHeader = true;
      }

      continue;
    }

    if (t === '') {
      continue;
    }

    const row = t.startsWith('|') ? cells(t) : [];

    if (row.length && row.every((c) => /^:?-+:?$/.test(c))) {
      continue;
    }

    if (row.length !== header.length) {
      throw new Error(`cannot read the ${heading} line "${t}" (want ${header.length} cells as in ${want}, or move prose below the table under its own heading)`);
    }

    rows.push({ row, text: t });
  }

  if (!seenHeader) {
    throw new Error(`no table under "${heading}"`);
  }

  return rows;
}

const splitLines = (text) => text.split('\n').map((l) => l.replace(/\r$/, ''));

// Rows of the *Question changes* table: [{ q, writes, since, presentWhen }].
export function questionChanges(blueprint) {
  return tableUnder(splitLines(blueprint), TABLE_HEADING, ['Question', 'Writes', 'Since', 'Present when']).map(({ row, text }) => {
    const q = /^Q?(\d+)$/i.exec(row[0]);
    const since = normalizeVersion(row[2]);

    if (!q || !since || !row[1]) {
      throw new Error(`cannot read the ${TABLE_HEADING} row "${text}" (want | Q<n> | <what it writes> | X.Y.Z | <text, or empty> |)`);
    }

    if (!WRITES.test(row[1])) {
      throw new Error(`the ${TABLE_HEADING} row "${text}" names no known Writes form (see ### Writes forms)`);
    }

    return { q: Number(q[1]), writes: row[1], since, presentWhen: row[3] };
  });
}

// Rows of the *Heading renames* table: [{ from, to, since }], in table order.
export function headingRenames(blueprint) {
  return tableUnder(splitLines(blueprint), RENAMES_HEADING, ['Old', 'New', 'Since']).map(({ row, text }) => {
    const since = normalizeVersion(row[2]);

    if (!HEADING_CELL.test(row[0]) || !HEADING_CELL.test(row[1]) || !since) {
      throw new Error(`cannot read the ${RENAMES_HEADING} row "${text}" (want | ## <old> | ## <new> | X.Y.Z |)`);
    }

    return { from: row[0], to: row[1], since };
  });
}

// The frontmatter block: line 1 (after a BOM) is `---`, the block closes at
// the next line that is `---` once trimmed, and every line between could be
// YAML. Returns { bom, lines, close }, close -1 when there is no such block.
export function frontmatter(text) {
  const bom = text.startsWith(BOM) ? BOM : '';
  const lines = text.slice(bom.length).split('\n');
  let close = lines[0].trim() === '---' ? lines.findIndex((l, i) => i > 0 && l.trim() === '---') : -1;

  if (close > 0 && !lines.slice(1, close).every((l) => YAML_LINE.test(l.replace(/\r$/, '')))) {
    close = -1;
  }

  return { bom, lines, close };
}

// The file's stamp as X.Y.Z, or null when absent or not a version.
export function stampOf(text) {
  const { lines, close } = frontmatter(text);

  if (close < 0) {
    return null;
  }

  const raw = scalarField(lines.slice(1, close).map((l) => l.replace(/\r$/, '')).join('\n'), 'myspec_version');

  return raw ? normalizeVersion(raw) || null : null;
}

// What a row writes to, without its form: rows for the same question and
// target are one change, asked in its newest form.
const target = (writes) => writes.replace(/ \([^)]*\)$/, '');

// The rows newer than the stamp: per question and target, the newest row; a
// question whose releases wrote to different targets is asked for each.
export function pending(rows, stamp) {
  const newest = new Map();

  for (const r of rows) {
    const key = `${r.q} ${target(r.writes)}`;
    const kept = newest.get(key);

    if (compareVersions(r.since, stamp ?? BASE_VERSION) > 0 && (!kept || compareVersions(r.since, kept.since) >= 0)) {
      newest.set(key, r);
    }
  }

  return [...newest.values()].sort((a, b) => a.q - b.q || compareVersions(a.since, b.since));
}

// A heading as compared: `#`s, one space, the words with inner whitespace
// collapsed and any closing `#`s dropped (`##  Imports ##` -> `## Imports`).
export function normalHeading(text) {
  const m = /^(#{1,6})[ \t]+(.*?)(?:[ \t]+#+)?[ \t]*$/.exec(text.trim());

  return m ? `${m[1]} ${m[2].replace(/\s+/g, ' ')}` : text.trim();
}

const ATX = /^ {0,3}(#{1,6})[ \t]+\S/;
const FENCE = /^ {0,3}(`{3,}|~{3,})(.*)$/;

// The file parsed once: { bom, lines, headings, fenced }. `headings` are the
// ATX headings outside frontmatter and code (fenced, or indented four spaces),
// in order, as { index, level, text } with text normalised; `fenced` holds
// the indices of fence and fenced lines. A fence closes only on a bare run of
// its own character at least as long (CommonMark), so ```md never closes one.
export function parseFile(text) {
  const { bom, lines, close } = frontmatter(text);
  const headings = [];
  const fenced = new Set();
  let fence = null;

  for (let i = close + 1; i < lines.length; i++) {
    const line = lines[i].replace(/\r$/, '');
    const f = FENCE.exec(line);

    if (fence !== null) {
      fenced.add(i);

      if (f && f[1][0] === fence[0] && f[1].length >= fence.length && f[2].trim() === '') {
        fence = null;
      }

      continue;
    }

    if (f && !(f[1][0] === '`' && f[2].includes('`'))) {
      fence = f[1];
      fenced.add(i);
      continue;
    }

    const h = ATX.exec(line);

    if (h) {
      headings.push({ index: i, level: h[1].length, text: normalHeading(line) });
    }
  }

  return { bom, lines, headings, fenced };
}

// The body of the section headed `heading` (its lines up to the next heading
// of the same or a higher level, code fences left out), or null when the file
// has no such heading.
function sectionBody(parsed, heading) {
  const { lines, headings, fenced } = parsed;
  const want = normalHeading(heading);
  const at = headings.findIndex((h) => h.text === want);

  if (at < 0) {
    return null;
  }

  const next = headings.slice(at + 1).find((h) => h.level <= headings[at].level);
  const end = next ? next.index : lines.length;

  return lines.filter((l, i) => i > headings[at].index && i < end && !fenced.has(i)).join('\n');
}

// The texts a *Present when* cell names: each `backticked` text when it has
// any ("`Configured against:` or `(none`"), else the whole cell.
export function presentTexts(cell) {
  const quoted = [...cell.matchAll(/`([^`]+)`/g)].map((m) => m[1]);

  return quoted.length ? quoted : cell === '' ? [] : [cell];
}

// Whether the file already holds what a question row writes: a new section's
// heading, or one of the row's *Present when* texts inside its target section.
export function present(parsed, row) {
  const heading = target(row.writes);

  if (!heading.startsWith('#')) {
    return false;
  }

  const body = sectionBody(parsed, heading);

  if (/\(new section\)$/.test(row.writes)) {
    return body !== null;
  }

  return body !== null && presentTexts(row.presentWhen).some((t) => body.includes(t));
}

// The renames the file still needs, whatever its stamp: it has the old
// heading and no heading the rename chain leads to (A→B, then B→C: B and C).
// A file that already has one of those is a conflict: renaming would leave
// two sections of one name, or the section under a name no skill reads, so
// it is reported for a hand merge instead and nothing is written.
export function pendingRenames(renames, parsed) {
  const names = new Set(parsed.headings.map((h) => h.text));
  const norm = renames.map((r) => ({ ...r, from: normalHeading(r.from), to: normalHeading(r.to) }));
  const apply = [];
  const conflicts = [];

  norm.forEach((r, i) => {
    if (!names.has(r.from)) {
      return;
    }

    const chain = [r.to];

    for (const later of norm.slice(i + 1)) {
      if (later.from === chain.at(-1)) {
        chain.push(later.to);
      }
    }

    const taken = chain.find((n) => names.has(n));

    if (taken) {
      conflicts.push({ ...r, to: taken });
    } else {
      apply.push(r);
      names.delete(r.from);
      names.add(r.to);
    }
  });

  return { apply, conflicts };
}

// A question row whose target heading a rename moves away would be asked
// again and write a section under the old name, so the tables must agree.
export function checkTables(questions, renames) {
  for (const q of questions) {
    const old = renames.find((r) => normalHeading(r.from) === normalHeading(target(q.writes)));

    if (old) {
      throw new Error(`the ${TABLE_HEADING} row for Q${q.q} targets "${old.from}", which ${RENAMES_HEADING} renames to "${old.to}"; name the new heading`);
    }
  }
}

// Rewrites the heading lines the renames name, keeping each line's ending.
export function withRenames(parsed, renames) {
  const lines = [...parsed.lines];
  const headings = parsed.headings.map((h) => ({ ...h }));

  for (const r of renames) {
    for (const h of headings.filter((x) => x.text === r.from)) {
      const cr = lines[h.index].endsWith('\r') ? '\r' : '';

      lines[h.index] = `${r.to}${cr}`;
      h.text = r.to;
    }
  }

  return parsed.bom + lines.join('\n');
}

// Sets `myspec_version` in the existing frontmatter block. Returns null when
// there is no closed block.
export function withStamp(text, version) {
  const { bom, lines, close } = frontmatter(text);

  if (close < 0) {
    return null;
  }

  const cr = lines[0].endsWith('\r') ? '\r' : '';
  const line = `myspec_version: ${version}${cr}`;
  const at = lines.findIndex((l, i) => i > 0 && i < close && /^myspec_version:/.test(l));

  if (at > 0) {
    lines[at] = line;
  } else {
    lines.splice(close, 0, line);
  }

  return bom + lines.join('\n');
}

export function pluginVersion(root = PLUGIN_ROOT) {
  const manifest = JSON.parse(readFileSync(join(root, 'framework-files', 'manifest.json'), 'utf8'));
  const version = normalizeVersion(manifest.frameworkVersion);

  if (!version) {
    throw new Error(`plugin manifest frameworkVersion "${manifest.frameworkVersion}" is not a version`);
  }

  return version;
}

// The nearest directory at or above `from` holding .myspec.json, else `from`.
export function projectRoot(from) {
  for (let dir = resolve(from); ; dir = dirname(dir)) {
    if (existsSync(join(dir, '.myspec.json'))) {
      return dir;
    }

    if (dirname(dir) === dir) {
      return resolve(from);
    }
  }
}

const USAGE = 'usage: mockup-config-check.mjs [--root <checkout>] [--file <path>] [--blueprint <path>] [--apply-renames | --stamp]\n';

function main(argv) {
  const opts = { '--root': null, '--file': null, '--blueprint': null };
  let action = null;

  for (let i = 0; i < argv.length; i++) {
    if ((argv[i] === '--stamp' || argv[i] === '--apply-renames') && action === null) {
      action = argv[i];
    } else if (Object.hasOwn(opts, argv[i]) && argv[i + 1] !== undefined) {
      opts[argv[i]] = argv[++i];
    } else {
      process.stderr.write(USAGE);

      return 2;
    }
  }

  const root = opts['--root'] ? resolve(opts['--root']) : projectRoot(process.cwd());
  const file = opts['--file'] ? resolve(root, opts['--file']) : resolve(root, aiDirFor(root), 'conventions', 'mockup-design.md');
  const blueprintPath = opts['--blueprint'] ? resolve(root, opts['--blueprint']) : join(PLUGIN_ROOT, 'blueprints', 'mockup.md');
  const rel = relative(root, file) || file;

  if (!existsSync(file)) {
    process.stdout.write(`mockup-config-check: ${rel} does not exist; /myspec:setup mockup generates it\n`);

    return 4;
  }

  const text = readFileSync(file, 'utf8');

  if (action === '--stamp') {
    const version = pluginVersion();
    const stamped = withStamp(text, version);

    if (stamped === null) {
      process.stderr.write(`mockup-config-check: ${rel} has no closed frontmatter block to stamp; give it one (--- … ---), then stamp\n`);

      return 2;
    }

    writeFileSync(file, stamped);
    process.stdout.write(`stamped: ${rel}  myspec_version: ${version}\n`);

    return 0;
  }

  const blueprint = readFileSync(blueprintPath, 'utf8');
  const stamp = stampOf(text);
  const allRenames = headingRenames(blueprint);
  const questions = questionChanges(blueprint);

  checkTables(questions, allRenames);

  const parsed = parseFile(text);
  const { apply: renames, conflicts } = pendingRenames(allRenames, parsed);

  if (action === '--apply-renames') {
    if (renames.length) {
      writeFileSync(file, withRenames(parsed, renames));
    }

    const lines = renames.map((r) => `renamed: ${r.from} -> ${r.to}  (since ${r.since})`);

    lines.push(`mockup-config-check: ${renames.length} heading(s) renamed`);
    process.stdout.write(`${lines.join('\n')}\n`);

    return 0;
  }

  // Questions are judged against the file as it will read once renamed.
  const renamed = renames.length ? parseFile(withRenames(parsed, renames)) : parsed;
  const rows = pending(questions, stamp);
  const asks = rows.filter((r) => !present(renamed, r));
  const out = [`file: ${rel}  myspec_version: ${stamp ?? `unstamped (counted as ${BASE_VERSION})`}`];

  for (const r of renames) {
    out.push(`rename: ${r.from} -> ${r.to}  (since ${r.since})`);
  }

  for (const r of conflicts) {
    out.push(`conflict: ${r.from} and ${r.to} both exist; merge ${r.from} into ${r.to} by hand, nothing renamed  (since ${r.since})`);
  }

  for (const r of rows) {
    out.push(`${asks.includes(r) ? 'ask' : 'present'}: Q${r.q}  writes: ${r.writes}  (since ${r.since})`);
  }

  out.push(`mockup-config-check: ${renames.length} rename(s) to apply, ${conflicts.length ? `${conflicts.length} conflict(s), ` : ''}${asks.length} question(s) to ask${rows.length > asks.length ? `, ${rows.length - asks.length} already present` : ''}`);
  process.stdout.write(`${out.join('\n')}\n`);

  return renames.length || conflicts.length || asks.length ? 3 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  let status;

  try {
    status = main(process.argv.slice(2));
  } catch (err) {
    // An unreadable blueprint, manifest or file: report it, never a stack trace.
    process.stderr.write(`mockup-config-check: ${err.message}\n`);
    status = 2;
  }

  process.exit(status);
}
